cat > crates/core/tests/issue17_slice21.rs <<'EOF'
//! Slice 21: Dragon-Scarred Bear regeneration.
mod common;
use aperture_core::catalog;
#[test]
fn dragon_scarred_bear_is_sourced_and_supported() {
    let card = catalog::by_name("Dragon-Scarred Bear")
        .expect("Dragon-Scarred Bear must be supported")
        .def();
    assert_eq!(card.cost, Some("{2}{G}"));
    assert_eq!(card.type_line, "Creature — Bear");
    assert_eq!(card.power, Some(3));
    assert_eq!(card.toughness, Some(2));
    assert_eq!(card.oracle, "Formidable — {1}{G}: Regenerate this creature. Activate only if creatures you control have total power 8 or greater.");
}
EOF
cargo test -q -p aperture-core --test issue17_slice21 2>&1 | tail -6

